<?php require 'includes/database.php';require 'includes/auth.php';requireLogin('customer');$st=$pdo->prepare("SELECT b.*,s.name shop_name,sv.name service_name FROM bookings b JOIN shops s ON s.id=b.shop_id JOIN services sv ON sv.id=b.service_id WHERE b.customer_id=? ORDER BY b.created_at DESC");$st->execute([$_SESSION['user']['id']]);$rows=$st->fetchAll();require 'includes/header.php';?><main class="wrap"><h2>บัญชีของฉันและสถานะการจอง</h2><div class="card"><table><tr><th>ร้าน</th><th>บริการ</th><th>วัน/เวลา</th><th>ชำระเงิน</th><th>สถานะ</th></tr><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['shop_name'])?></td><td><?=htmlspecialchars($r['service_name'])?></td><td><?=$r['booking_date']?> <?=substr($r['booking_time'],0,5)?></td><td><?=$r['payment_status']?></td><td><?=$r['booking_status']?></td></tr><?php endforeach;?></table></div></main><?php require 'includes/footer.php';?>
